// docs/specs/builtin-agent.md B6, B7: the built-in agent's tools and system text come from
// vimma-ctl's MCP fixture and INSTRUCTIONS, generated by `npm run gen-agent-tools`, so a tool
// changes in one place. These tests fail when the generated module drifts from its sources.
import { readFileSync } from "node:fs";
import { describe, expect, test } from "vitest";
import { AGENT_INSTRUCTIONS, AGENT_TOOL_LIST, agentTools } from "../src/agent-tools.mjs";
import { rustStringConst } from "../../../tools/gen-agent-tools.mjs";

const root = new URL("../../../", import.meta.url);
const fixture = JSON.parse(
  readFileSync(new URL("tools/vimma-ctl/tests/fixtures/mcp/tools-list.json", root), "utf8"),
);
const mcpRs = readFileSync(new URL("tools/vimma-ctl/src/mcp.rs", root), "utf8");
const regen = "out of date: run `npm run gen-agent-tools`";

describe("agent tools", () => {
  test("the built-in tool list equals the MCP fixture", () => {
    expect(AGENT_TOOL_LIST, regen).toEqual(fixture.tools);
  });

  test("the system text equals vimma-ctl's INSTRUCTIONS", () => {
    expect(AGENT_INSTRUCTIONS, regen).toBe(rustStringConst(mcpRs, "INSTRUCTIONS"));
    expect(AGENT_INSTRUCTIONS).toMatch(/^Vimma is the user's web browser\. These tools reach/);
    expect(AGENT_INSTRUCTIONS).not.toMatch(/\\|\n| {2}/);
  });

  test("screenshot is left out for a provider without vision", () => {
    const names = (/** @type {boolean} */ vision) => agentTools({ vision }).map((t) => t.name);
    expect(names(true)).toEqual(fixture.tools.map((/** @type {any} */ t) => t.name));
    expect(names(true)).toContain("vimma_screenshot");
    expect(names(false)).toEqual(names(true).filter((n) => n !== "vimma_screenshot"));
  });

  test("each tool carries only what a provider takes: name, description, input schema", () => {
    for (const t of agentTools({ vision: true })) {
      expect(Object.keys(t).sort()).toEqual(["description", "inputSchema", "name"]);
      expect(t.inputSchema.type).toBe("object");
    }
  });
});

describe("rustStringConst", () => {
  test("joins continued lines and reads escapes", () => {
    const src = [
      'pub const A: &str = "one \\',
      '    two \\"quoted\\" \\\\ back\\nslash";',
      'pub const B: &str = "b";',
    ].join("\n");
    expect(rustStringConst(src, "A")).toBe('one two "quoted" \\ back\nslash');
    expect(rustStringConst(src, "B")).toBe("b");
  });

  test("a missing constant is an error", () => {
    expect(() => rustStringConst("const X: u8 = 1;", "INSTRUCTIONS")).toThrow(/INSTRUCTIONS/);
  });
});
